<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1.0">
<title>Snake</title>
<style>
  *, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }
  body {
    background: #1a1a2e;
    color: #e0e0e0;
    font-family: 'Segoe UI', Tahoma, Geneva, Verdana, sans-serif;
    display: flex;
    justify-content: center;
    align-items: center;
    min-height: 100vh;
    flex-direction: column;
  }
  h1 { margin-bottom: 12px; font-size: 2rem; color: #00ff88; text-shadow: 0 0 10px rgba(0,255,136,.4); }
  #score {
    font-size: 1.4rem;
    margin-bottom: 10px;
    min-height: 1.8rem;
    color: #ffcc00;
    text-shadow: 0 0 6px rgba(255,204,0,.3);
  }
  #snake {
    display: block;
    border: 2px solid #00ff88;
    border-radius: 4px;
    box-shadow: 0 0 30px rgba(0,255,136,.15);
    background: #0f0f1a;
  }
  .controls {
    margin-top: 14px;
    display: flex;
    gap: 12px;
  }
  button {
    padding: 10px 28px;
    font-size: 1rem;
    border: none;
    border-radius: 6px;
    cursor: pointer;
    font-weight: 600;
    transition: background .15s, transform .1s;
  }
  button:active { transform: scale(.96); }
  #start { background: #00cc6a; color: #fff; }
  #start:hover { background: #00ee7a; }
  #pause { background: #ffaa00; color: #1a1a2e; }
  #pause:hover { background: #ffbb33; }
  #reset { background: #cc3333; color: #fff; }
  #reset:hover { background: #ee4444; }
  .info { margin-top: 10px; font-size: .85rem; color: #666; }
</style>
</head>
<body>

<h1>🐍 Snake</h1>
<div id="score">Score: 0</div>
<canvas id="snake" width="400" height="400"></canvas>
<div class="controls">
  <button id="start">▶ Start</button>
  <button id="pause">⏸ Pause</button>
  <button id="reset">↺ Reset</button>
</div>
<div class="info">Use arrow keys to steer · eat food to grow</div>

<script>
(function () {
  const canvas = document.getElementById('snake');
  const ctx = canvas.getContext('2d');
  const scoreEl = document.getElementById('score');

  // --- grid config (≥10×10) ---
  const GRID = 20;               // cells across/down
  const CELL = canvas.width / GRID;   // 20 px per cell

  let snake_, dir_, nextDir_, food_, alive_, score_, w_, h_, interval_;

  function init() {
    w_ = GRID;
    h_ = GRID;
    // snake starts at centre, length 3, heading right: head is last element
    const cx = Math.floor(w_ / 2);
    const cy = Math.floor(h_ / 2);
    snake_ = [
      [cx, cy],        // tail
      [cx - 1, cy],
      [cx - 2, cy]     // head
    ];
    dir_ = 'right';
    nextDir_ = null;            // pending turn (processed on tick)
    food_ = placeFood();
    alive_ = true;
    score_ = 0;
    scoreEl.textContent = 'Score: 0';
  }

  function freeCells() {
    const occupied = new Set(snake_.map(s => s[0] + ',' + s[1]));
    const cells = [];
    for (let x = 0; x < w_; x++)
      for (let y = 0; y < h_; y++)
        if (!occupied.has(x + ',' + y)) cells.push([x, y]);
    return cells;
  }

  function placeFood() {
    const free = freeCells();
    if (free.length === 0) return [0, 0]; // shouldn't happen while alive
    return free[Math.floor(Math.random() * free.length)];
  }

  function opposite(a, b) {
    return (a === 'up' && b === 'down') ||
           (a === 'down' && b === 'up') ||
           (a === 'left' && b === 'right') ||
           (a === 'right' && b === 'left');
  }

  function head() { return snake_[snake_.length - 1]; }

  function tick() {
    if (!alive_) return;

    // Apply queued direction (ignore 180° reversal)
    if (nextDir_ !== null && !opposite(nextDir_, dir_)) {
      dir_ = nextDir_;
    }
    nextDir_ = null;

    const [hx, hy] = head();
    let nx = hx, ny = hy;
    if (dir_ === 'up')    ny--;
    if (dir_ === 'down')  ny++;
    if (dir_ === 'left')  nx--;
    if (dir_ === 'right') nx++;

    // Wall collision
    if (nx < 0 || nx >= w_ || ny < 0 || ny >= h_) {
      alive_ = false;
      render();
      return;
    }

    const newHead = [nx, ny];

    // Self collision (skip the tail because it will move away — unless we grow)
    let grows = (nx === food_[0] && ny === food_[1]);
    // Check collision with all segments except possibly the last tail cell
    const limit = grows ? snake_.length - 1 : snake_.length;
    for (let i = 0; i < limit; i++) {
      if (snake_[i][0] === nx && snake_[i][1] === ny) {
        alive_ = false;
        render();
        return;
      }
    }

    snake_.push(newHead);
    if (grows) {
      score_++;
      scoreEl.textContent = 'Score: ' + score_;
      food_ = placeFood();
    } else {
      snake_.shift();
    }

    render();
  }

  // --- drawing ---
  function render() {
    // Background
    ctx.fillStyle = '#0f0f1a';
    ctx.fillRect(0, 0, canvas.width, canvas.height);

    // Grid lines (subtle)
    ctx.strokeStyle = 'rgba(255,255,255,.03)';
    ctx.lineWidth = 0.5;
    for (let i = 0; i <= GRID; i++) {
      ctx.beginPath(); ctx.moveTo(i * CELL, 0); ctx.lineTo(i * CELL, canvas.height); ctx.stroke();
      ctx.beginPath(); ctx.moveTo(0, i * CELL); ctx.lineTo(canvas.width, i * CELL); ctx.stroke();
    }

    // Food (pulsing circle)
    const fx = food_[0] * CELL + CELL / 2;
    const fy = food_[1] * CELL + CELL / 2;
    const pulse = 0.85 + 0.15 * Math.sin(Date.now() / 300);
    ctx.fillStyle = '#ff3355';
    ctx.shadowColor = '#ff3355';
    ctx.shadowBlur = 12;
    ctx.beginPath();
    ctx.arc(fx, fy, (CELL / 2 - 2) * pulse, 0, Math.PI * 2);
    ctx.fill();
    ctx.shadowBlur = 0;

    // Snake
    snake_.forEach(function (seg, i) {
      const x = seg[0] * CELL;
      const y = seg[1] * CELL;
      const isHead = i === snake_.length - 1;
      const t = i / Math.max(snake_.length - 1, 1);

      // Gradient from tail to head
      const r = Math.round(0 + t * 0);
      const g = Math.round(180 + t * 75);
      const b = Math.round(80 + t * 56);
      ctx.fillStyle = isHead ? '#00ff88' : 'rgb(' + r + ',' + g + ',' + b + ')';

      if (isHead) {
        ctx.shadowColor = '#00ff88';
        ctx.shadowBlur = 10;
      } else {
        ctx.shadowBlur = 0;
      }

      const pad = isHead ? 0.5 : 1.5;
      ctx.beginPath();
      ctx.roundRect(x + pad, y + pad, CELL - pad * 2, CELL - pad * 2, 4);
      ctx.fill();
    });
    ctx.shadowBlur = 0;

    // Eyes on head
    const [hx, hy] = head();
    const cx = hx * CELL + CELL / 2;
    const cy = hy * CELL + CELL / 2;
    ctx.fillStyle = '#0f0f1a';
    let eOffX = 0, eOffY = 0;
    if (dir_ === 'up')   eOffY = -3;
    if (dir_ === 'down') eOffY = 3;
    if (dir_ === 'left') eOffX = -3;
    if (dir_ === 'right') eOffX = 3;

    const eyeSize = 2.5;
    ctx.beginPath(); ctx.arc(cx + eOffX - 3, cy + eOffY, eyeSize, 0, Math.PI * 2); ctx.fill();
    ctx.beginPath(); ctx.arc(cx + eOffX + 3, cy + eOffY, eyeSize, 0, Math.PI * 2); ctx.fill();

    // Game-over overlay
    if (!alive_) {
      ctx.fillStyle = 'rgba(0,0,0,.6)';
      ctx.fillRect(0, 0, canvas.width, canvas.height);
      ctx.fillStyle = '#ff3355';
      ctx.font = 'bold 36px sans-serif';
      ctx.textAlign = 'center';
      ctx.fillText('Game Over!', canvas.width / 2, canvas.height / 2 - 10);
      ctx.fillStyle = '#aaa';
      ctx.font = '20px sans-serif';
      ctx.fillText('Score: ' + score_, canvas.width / 2, canvas.height / 2 + 25);
    }
  }

  // --- API ---
  const game = {
    get w() { return w_; },
    get h() { return h_; },

    reset: function () {
      clearInterval(interval_);
      interval_ = null;
      init();
      render();
    },

    tick: function () { tick(); },

    setDir: function (d) {
      if (!alive_) return;
      // Ignore 180° reversal immediately
      if (opposite(d, dir_)) return;
      nextDir_ = d;
    },

    setFood: function (x, y) { food_ = [x, y]; render(); },

    snake: function () { return snake_.map(function (s) { return s.slice(); }); },

    food: function () { return food_.slice(); },

    alive: function () { return alive_; },

    score: function () { return score_; }
  };
  window.game = game;

  // --- arrow-key input ---
  document.addEventListener('keydown', function (e) {
    const keyMap = {
      ArrowUp: 'up', ArrowDown: 'down',
      ArrowLeft: 'left', ArrowRight: 'right'
    };
    if (keyMap[e.key]) {
      e.preventDefault();
      game.setDir(keyMap[e.key]);
    }
  });

  // --- buttons ---
  document.getElementById('start').addEventListener('click', function () {
    if (!alive_) return;
    if (interval_) return;
    interval_ = setInterval(tick, 120);
    this.style.background = '#00995a';
    this.textContent = '▶ Running';
  });

  document.getElementById('pause').addEventListener('click', function () {
    if (!interval_) return;
    clearInterval(interval_);
    interval_ = null;
    this.textContent = '⏸ Pause';
    this.style.background = '#ffaa00';
    document.getElementById('start').textContent = '▶ Start';
    document.getElementById('start').style.background = '';
  });

  document.getElementById('reset').addEventListener('click', function () {
    game.reset();
    clearInterval(interval_);
    interval_ = null;
    document.getElementById('start').textContent = '▶ Start';
    document.getElementById('start').style.background = '';
    document.getElementById('pause').textContent = '⏸ Pause';
    document.getElementById('pause').style.background = '';
  });

  // --- initial render & animation loop for pulsing food ---
  init();
  render();
})();
</script>
</body>
</html>
